## What you did
I was playing around with multiple windows, essentially like so:
```rs
use bevy::prelude::*;

#[derive(Resource)]
struct WindowCounter(pub usize);

fn main() {
    App::new()
        .insert_resource(WindowCounter(1))
        .add_plugins(DefaultPlugins.set(WindowPlugin {
            primary_window: Some(Window {
                title: "Window #0".into(),
                ..Default::default()
            }),
            ..Default::default()
        }))
        .add_systems(Update, open_new_window_on_keypress)
        .run();
}

fn open_new_window_on_keypress(
    input: Res<Input<KeyCode>>,
    mut commands: Commands,
    mut windows: ResMut<WindowCounter>,
) {
    if input.just_released(KeyCode::Space) {
        let name = format!("Window #{}", windows.0);

        commands.spawn((
            Window {
                title: name.clone(),
                ..Default::default()
            },
            Name::new(name),
        ));

        windows.0 += 1;
    }
}

```

## What went wrong
Upon closing any window (via Super + Q/Alt + F4 or the close button), there's a pretty small chance that the entire application crashes:
